"acts_dataset = replaceActIds(acts_dataset)\n",
"acts_dataset[\"episode-act\"]= acts_dataset[\"episode\"].apply(float) + acts_dataset[\"act\"].apply(float) \n",
"acts_dataset.to_csv(\"../data/actInfo.csv\", index=False)"
]
